declare(strict_types=1);require __DIR__.'/app/request-distribution.php';$token=(string)($_GET['t']??'');try{$link=request_share_resolve($token);$request=rows("SELECT r.*,o.name requester_name,t.name equipment_type,loc.canonical_name location_name,loc.country_name FROM marketplace_requests r JOIN owners o ON o.id=r.organization_id JOIN equipment_types t ON t.id=r.equipment_type_id JOIN marketplace_locations loc ON loc.id=r.required_location_id WHERE r.id=?",[$link['request_id']])[0];$pageTitle=$request['title'];}catch(Throwable $error){http_response_code($error instanceof DomainException?$error->getCode():404);$problem=$error->getMessage();$pageTitle='Shared equipment request';}require __DIR__.'/includes/marketplace-header.php';?>
<?php if(isset($problem)):?><section class="market-empty"><h1>Request link unavailable</h1><p><?= e($problem) ?></p></section><?php else:?><main class="shared-request-page"><section class="shared-request-summary"><p class="request-kind">Equipment Required</p><h1><?= e($request['title']) ?></h1><p><?= e($request['description']) ?></p><div class="request-facts"><article><span>Equipment</span><strong><?= e($request['equipment_type']) ?></strong></article><article><span>Quantity</span><strong><?= (int)$request['quantity_required'] ?></strong></article><article><span>Intent</span><strong><?= e($request['intent']) ?></strong></article><article><span>Location</span><strong><?= e(implode(', ',array_filter([$request['location_name'],$request['country_name']]))) ?></strong></article><article><span>Required</span><strong><?= e($request['required_from'].($request['required_until']?' – '.$request['required_until']:'')) ?></strong></article><article><span>Responses close</span><strong><?= e($request['response_deadline']) ?></strong></article></div><p class="external-verification-note"><strong>External supplier response:</strong> submitting does not claim verified ownership, OEM authorization, or subscription status.</p></section><section class="transaction-panel external-response-panel"><h2>Supply this equipment</h2><p>Identify your company, proposed equipment, availability, and commercial terms.</p><?php if(!empty($_GET['submitted'])):?><div class="market-notice" role="status">Response received. The requester will review your submission.</div><?php else:?><form action="request-external-action" method="post" enctype="multipart/form-data" class="form-grid"><?php if(current_user()):?><?= csrf_field() ?><?php endif;?><input type="hidden" name="token" value="<?= e($token) ?>"><label>Contact name<input name="contact_name" required maxlength="255"></label><label>Company<input name="company_name" required maxlength="255"></label><label>Email<input type="email" name="contact_email" required maxlength="255"></label><label>Phone<input name="contact_phone" maxlength="50"></label><label class="full">Equipment proposed<textarea name="equipment_description" required></textarea></label><label>OEM / manufacturer<input name="oem_name"></label><label>Model<input name="model_name"></label><label>Quantity available<input type="number" name="quantity_offered" min="1" value="1" required></label><label>Availability from<input type="date" name="availability_from" required></label><label>Availability until<input type="date" name="availability_until"></label><label>Rate / price<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Currency<input name="currency" value="NGN" maxlength="3" required></label><label>Pricing basis<select name="pricing_basis"><option>DAILY</option><option>HOURLY</option><option>WEEKLY</option><option>MONTHLY</option><option>PROJECT</option><option>FIXED</option></select></label><label class="full">Technical response<textarea name="technical_response"></textarea></label><label class="full">Notes<textarea name="notes"></textarea></label><label class="full">Supporting document<input type="file" name="supporting_document" accept=".pdf,.docx,image/jpeg,image/png"></label><div class="full"><button class="market-button">Submit supply response</button></div></form><?php endif;?></section></main><?php endif;?>
